// Deterministic offline build. The packed source contains only the selected
// public-domain Natural Earth 10m feature coordinates, with geographic coordinate precision retained.
// See docs/mountain-europe-map-sources.md for inventory, source URLs and caveats.
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),zlib=require('node:zlib'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..');
const SOURCE_PACK='';
const source=JSON.parse(zlib.gunzipSync(Buffer.from(SOURCE_PACK,'base64')));
const core=fs.readFileSync(path.join(root,'assets/geography/core.js'),'utf8');
function declaration(name){const start=core.search(new RegExp('const '+name+'\\s*='));assert(start>=0,'Missing map source '+name);let quote=null,escaped=false;for(let i=start;i<core.length;i++){const c=core[i];if(quote){if(escaped)escaped=false;else if(c==='\\')escaped=true;else if(c===quote)quote=null;}else if(c==='"'||c==="'")quote=c;else if(c===';')return core.slice(start,i+1).replace(/^const/,'var');}throw Error('Unterminated map source '+name);}
const box={atob:s=>Buffer.from(s,'base64').toString('binary')};vm.createContext(box);
for(const name of ['COUNTRY_MAP_FILL_B64','COUNTRY_MAP_FILL_NAMES'])vm.runInContext(declaration(name),box);
vm.runInContext(core.slice(core.indexOf('function countryMapDecodeCompactPolygon('),core.indexOf('function countryMapLandData(')),box);
const world=vm.runInContext('countryMapDecodeCompactPolygon(COUNTRY_MAP_FILL_B64,COUNTRY_MAP_FILL_NAMES)',box);
const round=n=>Math.round(n*100)/100,rad=Math.PI/180;
const definitions={
 mountains:{title:'Fjellkjeder og høyland',en:'Mountain ranges and plateaus',width:1000,height:540,crop:[-180,180,-70,84],center:0}
};
function normalize(lon,center){while(lon-center>180)lon-=360;while(lon-center< -180)lon+=360;return lon;}
function position(ring,definition){let previous=definition.center;const unwrapped=ring.map(([lon,lat])=>{const current=normalize(lon,previous);previous=current;return[current,lat];});const xs=unwrapped.map(p=>p[0]),shift=Math.round((definition.center-(Math.min(...xs)+Math.max(...xs))/2)/360)*360;return unwrapped.map(([x,y])=>[x+shift,y]);}
function clipRing(input,[west,east,south,north]){let ring=input.slice();const edges=[[p=>p[0]>=west,(a,b)=>[west,a[1]+(b[1]-a[1])*(west-a[0])/(b[0]-a[0])]], [p=>p[0]<=east,(a,b)=>[east,a[1]+(b[1]-a[1])*(east-a[0])/(b[0]-a[0])]], [p=>p[1]>=south,(a,b)=>[a[0]+(b[0]-a[0])*(south-a[1])/(b[1]-a[1]),south]], [p=>p[1]<=north,(a,b)=>[a[0]+(b[0]-a[0])*(north-a[1])/(b[1]-a[1]),north]]];for(const[inside,intersection]of edges){if(!ring.length)break;const out=[];let prev=ring[ring.length-1],was=inside(prev);for(const p of ring){const is=inside(p);if(is!==was)out.push(intersection(prev,p));if(is)out.push(p);prev=p;was=is;}ring=out;}return ring.length>=3?ring:[];}
function polygonGeometries(geometry){return geometry.type==='Polygon'?[geometry.coordinates]:geometry.type==='MultiPolygon'?geometry.coordinates:[];}
function projectedPolygons(geometries,definition,project){return geometries.flatMap(g=>polygonGeometries(g)).flatMap(poly=>{const rings=poly.map(ring=>clipRing(position(ring,definition),definition.crop)).filter(r=>r.length).map(r=>clipRing(r.map(project),definition.projectedCrop||[0,definition.width,0,definition.height])).filter(r=>r.length);return rings.length?[rings]:[];});}
function area(ring){return Math.abs(ring.reduce((sum,p,i)=>{const q=ring[(i+1)%ring.length];return sum+p[0]*q[1]-q[0]*p[1];},0))/2;}
function inRing([x,y],ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
function inPoly(p,poly){return inRing(p,poly[0])&&!poly.slice(1).some(r=>inRing(p,r));}
function edgeDistance(p,ring){let best=Infinity;for(let i=0;i<ring.length;i++){const a=ring[i],b=ring[(i+1)%ring.length],dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy||1)));best=Math.min(best,Math.hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy));}return best;}
function interior(polys,blocked=[]){const poly=polys.slice().sort((a,b)=>area(b[0])-area(a[0]))[0];assert(poly,'Missing polygon geometry');let left=Math.min(...poly[0].map(p=>p[0])),right=Math.max(...poly[0].map(p=>p[0])),top=Math.min(...poly[0].map(p=>p[1])),bottom=Math.max(...poly[0].map(p=>p[1]));let best=null,score=-1;for(let pass=0;pass<4;pass++){const dx=(right-left)/22,dy=(bottom-top)/22;for(let x=0;x<=22;x++)for(let y=0;y<=22;y++){const p=[left+dx*x,top+dy*y];if(!inPoly(p,poly)||blocked.some(polys=>polys.some(q=>inPoly(p,q))))continue;const value=Math.min(...poly.map(r=>edgeDistance(p,r)),...blocked.flatMap(polys=>polys.flatMap(poly=>poly.map(r=>edgeDistance(p,r)))));if(value>score){best=p;score=value;}}if(!best)break;left=best[0]-dx;right=best[0]+dx;top=best[1]-dy;bottom=best[1]+dy;}return best||poly[0][0];}
function pathPolygons(polys){return polys.map(poly=>poly.map(ring=>ring.map(([x,y],i)=>(i?'L':'M')+round(x)+' '+round(y)).join('')+'Z').join('')).join('');}
function pathLines(lines){return lines.map(line=>line.map(([x,y],i)=>(i?'L':'M')+round(x)+' '+round(y)).join('')).join('');}
function projector(d){const[w,e,s,n]=d.crop;return([lon,lat])=>[(lon-w)/(e-w)*d.width,(n-lat)/(n-s)*d.height];}
function buildRegion(key,definition){const project=projector(definition),land=world.features.filter(f=>f.properties.name!=='Antarctica').flatMap(f=>projectedPolygons([f.geometry],definition,project)),landPath=pathPolygons(land),background=[{d:landPath,kind:'land'}],rows=source.ranges.map(row=>({...row,kind:row.kind||'range'}));
 const states=rows.map(row=>{const polys=projectedPolygons(row.geometries,definition,project);assert(polys.length,row.en+' is outside map');const point=interior(polys);assert(polys.some(p=>inPoly(point,p)),'Target outside '+row.en);return{n:row.n,en:row.en,d:pathPolygons(polys),c:point.map(round),kind:row.kind,...((polys.reduce((sum,p)=>sum+area(p[0]),0)<18)?{marker:true}:{}),_polys:polys,_area:polys.reduce((sum,p)=>sum+area(p[0]),0)};});
 // Larger parent regions are drawn first; Altiplano and Dolomites stay visible
 // inside their surrounding mountain chains. Hint points avoid overlaps.
 states.sort((a,b)=>b._area-a._area);
 for(let i=0;i<states.length;i++){const row=states[i],blocked=states.slice(i+1).map(r=>r._polys);if(blocked.some(polys=>polys.some(p=>inPoly(row.c,p))))row.c=interior(row._polys,blocked).map(round);delete row._polys;}
 for(const row of states){delete row._area;assert(row.d&&row.c.every(Number.isFinite),'Invalid target '+row.n);assert(!/NaN|Infinity/.test(row.d),'Invalid path '+row.n);assert(row.c[0]>=0&&row.c[0]<=definition.width&&row.c[1]>=0&&row.c[1]<=definition.height,'Target outside viewport '+row.n);}
 assert.equal(new Set(states.map(row=>row.n)).size,states.length,'Duplicate target names');
 return{title:definition.title,en:definition.en,viewBox:[0,0,definition.width,definition.height],background,states};
}
const regions=Object.fromEntries(Object.entries(definitions).map(([key,definition])=>[key,buildRegion(key,definition)]));
for(const state of regions.mountains.states)state.continent=require('./physical-map-continents.cjs')(state.en);
assert.equal(regions.mountains.states.length,34,'Expected 34 mountain ranges and plateaus');
const output=path.join(root,'assets/geography/physical-maps/mountain-europe.json'),result=JSON.stringify({version:1,regions})+'\n';
if(process.argv.includes('--check'))assert.equal(fs.readFileSync(output,'utf8').replace(/\r\n/g,'\n'),result,'Run scripts/build-mountain-europe-maps.cjs');else{fs.mkdirSync(path.dirname(output),{recursive:true});fs.writeFileSync(output,result);}
console.log(JSON.stringify({bytes:Buffer.byteLength(result),regions:Object.fromEntries(Object.entries(regions).map(([key,region])=>[key,{targets:region.states.length,kinds:Object.fromEntries([...new Set(region.states.map(s=>s.kind))].map(kind=>[kind,region.states.filter(s=>s.kind===kind).length]))}]))}));
